const body = $json.body || $json;

const search = (body.query || body.search || body.text || body.message || "").toLowerCase();
const limit = Number(body.limit || 10);

const query = `
query GetMemories {
  allAgenticsMemories(first: 200, orderBy: CREATED_AT_DESC) {
    nodes {
      id
      kind
      title
      content
      tags
      importance
      source
      createdAt
      updatedAt
    }
  }
}
`;

const res = await fetch("http://postgraphile:5000/graphql", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ query })
});

const data = await res.json();

if (data.errors) {
  return [{ json: { ok: false, errors: data.errors } }];
}

const memories = data.data.allAgenticsMemories.nodes || [];

const scored = memories.map(m => {
  const text = [
    m.kind || "",
    m.title || "",
    m.content || "",
    ...(m.tags || [])
  ].join(" ").toLowerCase();

  let score = 0;
  if (!search) score = 1;
  if (search && text.includes(search)) score += 10;
  for (const word of search.split(/\s+/).filter(Boolean)) {
    if (text.includes(word)) score += 1;
  }
  score += Number(m.importance || 0) / 10;

  return { ...m, score };
}).filter(m => m.score > 0)
  .sort((a, b) => b.score - a.score)
  .slice(0, limit);

return [{
  json: {
    ok: true,
    action: "memory_search",
    query: search,
    count: scored.length,
    results: scored
  }
}];
